diff --git a/internal/backend/search/adapter.go b/internal/backend/search/adapter.go
index 9e04763..513c201 100644
--- a/internal/backend/search/adapter.go
+++ b/internal/backend/search/adapter.go
@@ -196,6 +196,9 @@ func (a *Adapter) inspect(ctx context.Context, target string, native bool) (capa
 	if err == errTransport && ctx.Err() == nil {
 		return caps, protocol.Fail(pb.FailureCode_UNAVAILABLE, "index qualification transport failed")
 	}
+	if errors.Is(err, execution.ErrExecutionMemory) {
+		return caps, recordMemoryFailure()
+	}
 	if err != nil {
 		return caps, protocol.Fail(pb.FailureCode_UNAVAILABLE, "index qualification response unavailable")
 	}
diff --git a/internal/backend/search/batch.go b/internal/backend/search/batch.go
index 7412673..2932026 100644
--- a/internal/backend/search/batch.go
+++ b/internal/backend/search/batch.go
@@ -414,10 +414,9 @@ func (a *Adapter) executeRecords(ctx context.Context, works []*execution.Plan) [
 	if memory.reply != 0 {
 		// Exactly Runtime's sum(Plan.WorkingBytes) + max(IOReserve):
 		// sum(known input) + sum(item ACK) + one envelope/header window.
-		memory.reply += (64 << 10) + bulkAckEnvelopeWorking
-	} else {
-		memory.base += 64 << 10
+		memory.reply += bulkAckEnvelopeWorking
 	}
+	memory.reply += 64 << 10
 	ctx = context.WithValue(ctx, recordMemoryContextKey, memory)
 	works = append([]*execution.Plan(nil), works...)
 	readOnly := true
